        "조문참고자료": "[제목개정 2006.3.23]",
        "조문키": "0085001",
        "항": [
            {
                "항번호": "①",
                "항내용": "①법 제78조제1항 및 제2항에 따른 용적률은 다음 각 호의 범위에서 관할구역의 면적, 인구규모 및 용도지역의 특성 등을 고려하여 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 도시ㆍ군계획조례가 정하는 비율을 초과할 수 없다. <개정 2012.4.10, 2019.8.6, 2021.1.5>",
                "호": [
                    {
                        "호번호": "1.",
                        "호내용": "1. 제1종전용주거지역 : 50퍼센트 이상 100퍼센트 이하"
                    },
                    {
                        "호번호": "2.",
                        "호내용": "2. 제2종전용주거지역 : 50퍼센트 이상 150퍼센트 이하"
                    },
                    {
                        "호번호": "3.",
                        "호내용": "3. 제1종일반주거지역 : 100퍼센트 이상 200퍼센트 이하"
                    },
                    {
                        "호번호": "4.",
                        "호내용": "4. 제2종일반주거지역 : 100퍼센트 이상 250퍼센트 이하"
                    },
                    {
                        "호번호": "5.",
                        "호내용": "5. 제3종일반주거지역 : 100퍼센트 이상 300퍼센트 이하"
                    },
                    {
                        "호번호": "6.",
                        "호내용": "6. 준주거지역 : 200퍼센트 이상 500퍼센트 이하"
                    },
                    {
                        "호번호": "7.",
                        "호내용": "7. 중심상업지역 : 200퍼센트 이상 1천500퍼센트 이하"
                    },
                    {
                        "호번호": "8.",
                        "호내용": "8. 일반상업지역 : 200퍼센트 이상 1천300퍼센트 이하"
                    },
                    {
                        "호번호": "9.",
                        "호내용": "9. 근린상업지역 : 200퍼센트 이상 900퍼센트 이하"
                    },
                    {
                        "호번호": "10.",
                        "호내용": "10. 유통상업지역 : 200퍼센트 이상 1천100퍼센트 이하"
                    },
                    {
                        "호번호": "11.",
                        "호내용": "11. 전용공업지역 : 150퍼센트 이상 300퍼센트 이하"
                    },
                    {
                        "호번호": "12.",
                        "호내용": "12. 일반공업지역 : 150퍼센트 이상 350퍼센트 이하"
                    },
                    {
                        "호번호": "13.",
                        "호내용": "13. 준공업지역 : 150퍼센트 이상 400퍼센트 이하"
                    },
                    {
                        "호번호": "14.",
                        "호내용": "14. 보전녹지지역 : 50퍼센트 이상 80퍼센트 이하"
                    },
                    {
                        "호번호": "15.",
                        "호내용": "15. 생산녹지지역 : 50퍼센트 이상 100퍼센트 이하"
                    },
                    {
                        "호번호": "16.",
                        "호내용": "16. 자연녹지지역 : 50퍼센트 이상 100퍼센트 이하"
                    },
                    {
                        "호번호": "17.",
                        "호내용": "17. 보전관리지역 : 50퍼센트 이상 80퍼센트 이하"
                    },
                    {
                        "호번호": "18.",
                        "호내용": "18. 생산관리지역 : 50퍼센트 이상 80퍼센트 이하"
                    },
                    {
                        "호번호": "19.",
                        "호내용": "19. 계획관리지역 : 50퍼센트 이상 100퍼센트 이하"
                    },
                    {
                        "호번호": "20.",
                        "호내용": "20. 농림지역 : 50퍼센트 이상 80퍼센트 이하"
                    },
                    {
                        "호번호": "21.",
                        "호내용": "21. 자연환경보전지역 : 50퍼센트 이상 80퍼센트 이하"
                    }
                ]
            },
            {
                "항번호": "②",
                "항내용": "②제1항의 규정에 의하여 도시ㆍ군계획조례로 용도지역별 용적률을 정함에 있어서 필요한 경우에는 당해 지방자치단체의 관할구역을 세분하여 용적률을 달리 정할 수 있다. <개정 2012.4.10>"
            },
            {
                "항번호": "③",
                "항내용": "③ 제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 해당 지역의 용적률을 다음 각 호의 구분에 따라 완화할 수 있다. <개정 2018.7.17, 2022.1.28, 2023.3.21, 2024.3.19>",
                "호": [
                    {
                        "호번호": "1.",
                        "호내용": "1. 제1항제1호부터 제6호까지의 지역에서 「공공주택 특별법 시행령」 제2조에 따른 공공임대주택 또는 임대의무기간이 8년 이상인 「민간임대주택에 관한 특별법」 제2조제1호에 따른 민간임대주택을 건설하는 경우: 제1항제1호부터 제6호까지에 따른 용도지역별 최대한도의 120퍼센트 이내의 범위에서 도시ㆍ군계획조례로 정하는 비율"
                    },
                    {
                        "호번호": "2.",
                        "호내용": "2. 다음 각 목의 어느 하나에 해당하는 자가 「고등교육법」 제2조에 따른 학교의 학생이 이용하도록 해당 학교 부지 외에 「건축법 시행령」 별표 1 제2호라목에 따른 기숙사(이하 이 항에서 \"기숙사\"라 한다)를 건설하는 경우: 제1항 각 호에 따른 용도지역별 최대한도의 범위에서 도시ㆍ군계획조례로 정하는 비율",
                        "목": [
                            {
                                "목번호": "가.",
                                "목내용": "가. 국가 또는 지방자치단체"
                            },
                            {
                                "목번호": "나.",
                                "목내용": "나. 「사립학교법」에 따른 학교법인"
                            },
                            {
                                "목번호": "다.",
                                "목내용": "다. 「한국사학진흥재단법」에 따른 한국사학진흥재단"
                            },
                            {
                                "목번호": "라.",
                                "목내용": "라. 「한국장학재단 설립 등에 관한 법률」에 따른 한국장학재단"
                            },
                            {
                                "목번호": "마.",
                                "목내용": "마. 가목부터 라목까지의 어느 하나에 해당하는 자가 단독 또는 공동으로 출자하여 설립한 법인"
                            }
                        ]
                    },
                    {
                        "호번호": "3.",
                        "호내용": "3. 「고등교육법」 제2조에 따른 학교의 학생이 이용하도록 해당 학교 부지에 기숙사를 건설하는 경우: 제1항 각 호에 따른 용도지역별 최대한도의 범위에서 도시ㆍ군계획조례로 정하는 비율"
                    },
                    {
                        "호번호": "4.",
                        "호내용": "4. 「영유아보육법」 제14조제1항에 따른 사업주가 같은 법 제10조제4호의 직장어린이집을 설치하기 위하여 기존 건축물 외에 별도의 건축물을 건설하는 경우: 제1항 각 호에 따른 용도지역별 최대한도의 범위에서 도시ㆍ군계획조례로 정하는 비율"
                    },
                    {
                        "호번호": "5.",
                        "호내용": "5. 제10항 각 호의 어느 하나에 해당하는 시설을 국가 또는 지방자치단체가 건설하는 경우: 제1항 각 호에 따른 용도지역별 최대한도의 범위에서 도시ㆍ군계획조례로 정하는 비율"
                    },
                    {
                        "호번호": "6.",
                        "호내용": "6. 「건축법 시행령」 별표 1 제9호의 의료시설 부지에 「감염병의 예방 및 관리에 관한 법률」 제36조제3항 전단에 따른 감염병관리시설을 설치하는 경우로서 다음 각 목의 요건을 모두 갖춘 경우: 제1항 각 호에 따른 용도지역별 최대한도의 120퍼센트 이하의 범위에서 도시ㆍ군계획조례로 정하는 비율",
                        "목": [
                            {
                                "목번호": "가.",
                                "목내용": "가. 질병관리청장이 효율적인 감염병 관리를 위하여 필요하다고 인정하는 시설(이하 \"필요감염병관리시설\"이라 한다)을 설치하는 경우일 것"
                            },
                            {
                                "목번호": "나.",
                                "목내용": "나. 필요감염병관리시설 외 시설의 면적은 제1항에 따라 도시ㆍ군계획조례로 정하는 용적률에 해당하는 면적 이내일 것"
                            }
                        ]
                    }
                ]
            },
            {
                "항번호": "④",
                "항내용": "④제3항의 규정은 제46조제9항 각 호의 어느 하나에 해당되는 경우에는 이를 적용하지 아니한다. <신설 2005.9.8>"
            },
            {
                "항번호": "⑤",
                "항내용": "⑤ 제1항에도 불구하고 법 제37조제4항 후단에 따른 방재지구의 재해저감대책에 부합하게 재해예방시설을 설치하는 건축물의 경우 제1항제1호부터 제13호까지의 용도지역에서는 해당 용적률의 140퍼센트 이하의 범위에서 도시ㆍ군계획조례로 정하는 비율로 할 수 있다. <신설 2014.1.14, 2023.7.18>"
            },
            {
                "항번호": "⑥",
                "항내용": "⑥법 제78조제3항의 규정에 의하여 다음 각 호의 지역 안에서의 용적률은 각 호에서 정한 범위 안에서 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 도시ㆍ군계획조례가 정하는 비율을 초과하여서는 아니된다. <개정 2005.9.8, 2005.9.30, 2005.11.11, 2010.10.1, 2011.11.16, 2012.4.10, 2014.1.14>",
                "호": [
                    {
                        "호번호": "1.",
                        "호내용": "1. 도시지역외의 지역에 지정된 개발진흥지구 : 100퍼센트 이하"
                    },
                    {
                        "호번호": "2.",
                        "호내용": "2. 수산자원보호구역 : 80퍼센트 이하"
                    },
                    {
                        "호번호": "3.",
                        "호내용": "3. 「자연공원법」에 따른 자연공원: 100퍼센트 이하"
                    },
                    {
                        "호번호": "4.",
                        "호내용": "4. 「산업입지 및 개발에 관한 법률」 제2조제8호라목에 따른 농공단지(도시지역외의 지역에 지정된 농공단지에 한한다) : 150퍼센트 이하"
                    }
                ]
            },
